<script setup lang="ts">import {computed,nextTick,ref,watch} from "vue";import {useRoute,useRouter} from "vue-router";import {Plus,Send,Trash2,BookOpen,Quote} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import ZButton from "@/components/zs/ZButton.vue";import {answerFor,loadThreads,newThread,saveThreads,type ChatMessage,type ChatThread} from "@/lib/chat-storage";import {useCompanyStore} from "@/stores/company";import {setPageMeta} from "@/lib/page-meta";setPageMeta("Knowledge Chat","Threaded browser-persisted chat with citations from company documents.");const route=useRoute(),router=useRouter(),company=useCompanyStore(),threads=ref<ChatThread[]>(loadThreads(company.activeCompanyId)),draft=ref(""),busy=ref(false),input=ref<HTMLTextAreaElement|null>(null),scroller=ref<HTMLElement|null>(null);const threadId=computed(()=>String(route.params.threadId??"")),active=computed(()=>threads.value.find(x=>x.id===threadId.value));if(!active.value&&threads.value[0])void router.replace(`/knowledge/chat/${threads.value[0].id}`);const prompts=["What is the annual leave policy?","Summarize the month-end close checklist","Which documents can the Sales team access?"];function persist(){saveThreads(company.activeCompanyId,threads.value)}async function focus(){await nextTick();input.value?.focus();scroller.value?.scrollTo({top:scroller.value.scrollHeight,behavior:'smooth'})}async function create(){const x=newThread();threads.value.unshift(x);persist();await router.push(`/knowledge/chat/${x.id}`);await focus()}async function remove(id:string){threads.value=threads.value.filter(x=>x.id!==id);if(!threads.value.length)threads.value=[newThread()];persist();if(id===threadId.value)await router.push(`/knowledge/chat/${threads.value[0]?.id}`)}async function send(){const text=draft.value.trim(),t=active.value;if(!text||!t||busy.value)return;const user:ChatMessage={id:`m-${Date.now()}`,role:'user',createdAt:new Date().toISOString(),parts:[{type:'text',text}]};t.messages.push(user);if(t.title==='New conversation')t.title=text.slice(0,42);t.updatedAt=new Date().toISOString();draft.value='';busy.value=true;persist();await focus();setTimeout(async()=>{t.messages.push({id:`m-${Date.now()}-a`,role:'assistant',createdAt:new Date().toISOString(),parts:answerFor(text)});t.updatedAt=new Date().toISOString();busy.value=false;persist();await focus()},700)}watch(threadId,()=>void focus());watch(()=>company.activeCompanyId,async id=>{threads.value=loadThreads(id);await router.replace(`/knowledge/chat/${threads.value[0]?.id}`)});</script><template><AppShell><PageHeader title="Knowledge Chat" description="Separate conversations saved in this browser · answers cite accessible company documents"><template #actions><ZButton @click="create"><Plus class="size-4"/>New conversation</ZButton></template></PageHeader><div class="grid h-[calc(100vh-9rem)] min-h-[34rem] gap-4 lg:grid-cols-[16rem_1fr]"><Panel class="hidden lg:block" body-class="h-full"><div class="border-b border-line p-3"><p class="label-caps">Conversations</p></div><div class="max-h-[calc(100vh-14rem)] overflow-y-auto p-2"><div v-for="t in threads" :key="t.id" class="group mb-1 flex items-center rounded-md" :class="t.id===threadId?'bg-surface-selected':''"><button class="min-w-0 flex-1 px-3 py-2 text-left" @click="router.push(`/knowledge/chat/${t.id}`)"><p class="truncate text-xs font-medium text-content">{{t.title}}</p><p class="mt-0.5 text-2xs text-content-muted">{{t.messages.length}} messages</p></button><button class="mr-1 grid size-7 place-items-center rounded-md text-content-muted opacity-0 hover:bg-surface-hover group-hover:opacity-100" aria-label="Delete conversation" @click="remove(t.id)"><Trash2 class="size-3.5"/></button></div></div></Panel><Panel body-class="flex h-full min-h-0 flex-col"><div ref="scroller" class="min-h-0 flex-1 overflow-y-auto p-4 sm:p-6"><div v-if="!active?.messages.length" class="mx-auto flex h-full max-w-xl flex-col items-center justify-center text-center"><span class="grid size-12 place-items-center rounded-md bg-primary-subtle text-primary-subtle-fg"><BookOpen class="size-6"/></span><h2 class="mt-4 text-lg font-semibold text-content">Ask your company knowledge</h2><p class="mt-2 text-sm text-content-secondary">Search indexed policies, SOPs and spreadsheets available to your role.</p><div class="mt-5 flex flex-wrap justify-center gap-2"><button v-for="p in prompts" :key="p" class="rounded-md border border-line px-3 py-2 text-xs text-content-secondary hover:bg-surface-hover" @click="draft=p;focus()">{{p}}</button></div></div><div v-else class="mx-auto max-w-3xl space-y-5"><div v-for="m in active.messages" :key="m.id" :class="m.role==='user'?'flex justify-end':'block'"><div :class="m.role==='user'?'max-w-[85%] rounded-lg bg-primary px-4 py-3 text-sm text-primary-foreground':'text-sm leading-6 text-content'"><template v-for="(part,i) in m.parts" :key="i"><p v-if="part.type==='text'" class="whitespace-pre-wrap">{{part.text.replaceAll('**','')}}</p><div v-else class="mt-3 flex items-start gap-2 rounded-md border border-line bg-surface-sunken p-3"><Quote class="mt-0.5 size-3.5 text-content-brand"/><div><p class="text-xs font-medium text-content">{{part.title}}</p><p class="text-2xs text-content-muted">{{part.source}}</p></div></div></template></div></div><div v-if="busy" class="text-sm text-content-muted"><span class="animate-pulse">Searching company knowledge…</span></div></div></div><form class="border-t border-line p-3" @submit.prevent="send"><div class="rounded-md border border-line-strong bg-surface p-2 focus-within:ring-2 focus-within:ring-primary-subtle"><textarea ref="input" v-model="draft" autofocus class="min-h-20 w-full resize-none bg-transparent px-2 py-1 text-sm text-content outline-none" placeholder="Ask across company documents…" @keydown.enter.exact.prevent="send"></textarea><div class="flex items-center justify-between"><span class="text-2xs text-content-muted">Department access applies · Preview responses</span><ZButton type="submit" :disabled="!draft.trim()||busy" aria-label="Send message"><Send class="size-4"/>Send</ZButton></div></div></form></Panel></div></AppShell></template>